always-actions.script:
// Module gates for TRANSITIONS. pre-actions do NOT run for transition requests, so anything that must
// stop a transition has to be checked here in always-actions (which DO run for them). A transition
// request is one where targetTransitionActualName != null; a list SEARCH/filter posts to the SCREEN
// itself (ttan == null) and a plain screen GET is a render -> both fall through to the pre-actions
// gates. Framework column/find-pref transitions are whitelisted. ANY error FAILS OPEN so a request is
// never blocked on a gate fault.
//
// Two gates run here, mirroring the two in pre-actions so a transition is EXACTLY as permissive as the
// render of the same module. They deliberately cover DIFFERENT surfaces:
//   1. PLAN gate (ZE-GATE-001 writes, ZE-GATE-002 reads) — the tenant's plan must include the module.
//      Runs on GET *and* POST transitions: a module you don't pay for should be neither readable nor
//      writable. Only the platform super-admin (ADMIN) is exempt — a TENANT admin (ZENITH_ADMIN)
//      cannot grant itself a module its plan doesn't include, so ZENITH_ADMIN is NOT exempt here.
//   2. ROLE gate (ST-077 view-only / ST-078 no-access) — WRITES ONLY (POST). Moqui renders a
//      non-read-only transition as a POST, so POST+ttan is the write surface. ADMIN, ZENITH_ADMIN and
//      POS-only cashiers are exempt.
//
// CROSS-MODULE TRANSITIONS: a screen in module A may legitimately call a transition in module B, but the
// gate infers the module from the URL and so cannot tell that call apart from a direct hit. The plan
// decision + the _sharedTx registry that handles this now live in zenith.base.SecurityServices'
// check#ModulePlanAccess (ZE-GATE-004), which takes the module set as a PARAMETER — so any plan shape is
// testable by calling it, instead of INSERTing throwaway rows into saas_plan to build a fixture.
// Audited 2026-07-16: barcode/renderLabels is the ONLY cross-module transition in the codebase — every
// other cross-module URL targets a SCREEN (a render, gated in pre-actions). That is no longer a fact you
// have to remember: docs/infra/lint-cross-module-transitions.sh FAILS if a new one appears unregistered.
//
// WHY THE ROLE GATE IS NOT EXTENDED TO READS (ZE-GATE-002, deliberate — do not "fix" without checking
// this): the same URL-inference limit applies, but roles are far narrower than plans, so a role gate on
// reads breaks the shared call even with _sharedTx. The real instance: the POS screen
// zenith-erp-pos/.../Pos/BarcodeLabels.xml loads pos-barcode-labels.js, which GETs
// /apps/zenith/barcode/renderLabels (read-only, "the shared renderer for the POS bulk printer").
// ZENITH_CASHIER holds Z_POS=AUTHZA_ALL but has NO Z_BARCODE grant at all -> role-gating reads would
// silently break label printing for any cashier who is not posOnly (i.e. holds a 2nd role, cf.
// ZE-ROLES-001).
//
// MARUTHI-safe: the plan gate can only block a module the RENDER gate already blocks (same module set,
// same condition), so nothing reachable in the UI becomes unreachable. MARUTHI is on PROFESSIONAL,
// whose module set is a strict superset of the STARTER set it previously ran on -> no-op. Its cashiers
// are posOnly (role-gate exempt) and 'pos' is in every plan; its admins are ZENITH_ADMIN.
try {
    if (ec.web != null && ec.user.userId != null && !ec.user.isInGroup("ADMIN")) {
        def _ttan = sri.screenUrlInfo?.targetTransitionActualName
        def _fwTx = ['formSelectColumns','formSaveColumns','formSaveFind','formDeleteFind'] as Set
        boolean _isPost = "POST".equalsIgnoreCase(ec.web.getRequest()?.getMethod() ?: "")
        if (_ttan && !_fwTx.contains(_ttan)) {
            def _gate = ['pos','sales','purchase','inventory','accounting','contacts','crm','hr','payroll',
                'attendance','timeoff','recruitment','expenses','manufacturing','quality','maintenance','fleet',
                'helpdesk','marketing','ecommerce','events','subscriptions','documents','approvals','integrations',
                'website','studio','plm','fieldservice','discuss','sign','project','timesheets','tax','pricing','barcode'] as Set
            def uri = ec.web.getRequest()?.getRequestURI()
            def segs = uri ? uri.split('/').findAll{it} : []
            int zi = segs.findIndexOf{it.toLowerCase()=='zenith'}
            def _rm = (zi >= 0 && zi + 1 < segs.size()) ? segs[zi + 1].toLowerCase() : null
            def _shw = (uri ?: "").startsWith('/qapps/') ? '/qapps' : '/apps'
            if (_rm && _gate.contains(_rm)) {
                boolean _blocked = false
                // ---- 1. PLAN gate (ZE-GATE-001 writes + ZE-GATE-002 reads): GET and POST ----
                // Only gate when the request POSITIVELY resolves to an active SaaS tenant with a plan
                // module set; anything else (no org, not a tenant, lookup failure) passes.
                def _org = ec.user.getPreference('ACTIVE_ORGANIZATION')
                if (_org && _org != '_NA_') {
                    def _mods = null
                    boolean _dzp = ec.artifactExecution.disableAuthz()
                    try {
                        // cached: this runs on EVERY module transition (reads too — type-aheads,
                        // lookups, exports) incl. the POS cart hot path, so it must not hit the DB
                        def _tl = ec.entity.find("zenith.erp.saas.SaasTenant")
                                .condition("organizationPartyId", _org)
                                .condition("statusId", "SaasTenantActive").useCache(true).list()
                        if (_tl) {
                            _mods = new HashSet()
                            ec.entity.find("zenith.erp.saas.SaasPlanModule")
                                    .condition("planId", _tl[0].planId).useCache(true).list()
                                    .each { _mods.add(it.moduleId?.toLowerCase()) }
                        }
                    } finally { if (!_dzp) ec.artifactExecution.enableAuthz() }
                    if (_mods != null) {
                        // The DECISION (incl. the _sharedTx cross-module registry) lives in
                        // check#ModulePlanAccess so every plan shape is testable by CALLING it with a
                        // synthetic module set — no saas_plan/saas_plan_module writes to construct a
                        // fixture. disableAuthz: the gate must not depend on the caller's service authz.
                        // Block ONLY on an explicit false, so a null/failed call fails OPEN as before.
                        def _pa = ec.service.sync().name("zenith.base.SecurityServices.check#ModulePlanAccess")
                                .parameters([moduleId: _rm, transitionName: _ttan, planModules: (_mods as List)])
                                .disableAuthz().call()
                        if (_pa?.inPlan == false) {
                            ec.message.addError("That module isn't included in your current plan.")
                            sri.sendRedirectAndStopRender(_shw + "/zenith/Dashboard")
                            _blocked = true
                        }
                    }
                }
                // ---- 2. ROLE gate (ST-077 / ST-078): WRITES ONLY — see the read note above ----
                def _zr = (ec.user.userGroupIdSet ?: []).findAll { it?.startsWith("ZENITH_") && it != "ZENITH_ALL" }
                boolean _posOnly = (_zr.size() == 1 && _zr.contains("ZENITH_CASHIER"))
                if (_isPost && !_blocked && !_posOnly && !ec.user.isInGroup("ZENITH_ADMIN")) {
                    def _myG = (ec.user.userGroupIdSet ?: []) as List
                    boolean hasFull = true
                    if (_myG) {
                        boolean _dz = ec.artifactExecution.disableAuthz()
                        try {
                            hasFull = ec.entity.find("moqui.security.ArtifactAuthz")
                                    .condition("artifactGroupId", "Z_" + _rm.toUpperCase())
                                    .condition("userGroupId", "in", _myG)
                                    .condition("authzActionEnumId", "AUTHZA_ALL")
                                    .condition("authzTypeEnumId", "in", ["AUTHZT_ALLOW", "AUTHZT_ALWAYS"])
                                    .count() > 0
                        } finally { if (!_dz) ec.artifactExecution.enableAuthz() }
                    }
                    if (!hasFull) {
                        ec.message.addError("Your role has view-only access to this module — you can't make changes here.")
                        sri.sendRedirectAndStopRender(_shw + "/zenith/Dashboard")
                    }
                }
            }
        }
    }
} catch (Throwable e) { /* fail OPEN — never block a write on a gate error */ }

actions.script:
def q = ec.web.getRequest().getParameter("query")
def out = [response: null]
boolean _d = ec.artifactExecution.disableAuthz()
try {
    def r = ec.service.sync().name("zenith.base.AiServices.ask#Copilot").parameter("query", q).call()
    out.response = r?.response ?: "Sorry, I couldn't generate a response."
} catch (Exception e) {
    out.response = "Sorry, the assistant is unavailable right now."
} finally { if (!_d) ec.artifactExecution.enableAuthz() }
ec.web.sendJsonResponse(out)

def orgId = ec.user.getPreference("ACTIVE_ORGANIZATION")
def result = [isSaasTenant:false, hasAllAccess:false, posOnly:false, isAdmin:false, modules:[]]
// ZE-SETTINGS-0203: expose admin status so the /qapps menu-filter hides Settings from non-admins.
result.isAdmin = ec.user.isInGroup("ZENITH_ADMIN") || ec.user.isInGroup("ADMIN")
try {
    if (!ec.user.isInGroup("ADMIN")) {
        def _zr = (ec.user.userGroupIdSet ?: []).findAll { it?.startsWith("ZENITH_") && it != "ZENITH_ALL" }
        result.posOnly = (_zr.size() == 1 && _zr.contains("ZENITH_CASHIER"))
    }
} catch (Exception e) {}
if (orgId) {
    boolean d = ec.artifactExecution.disableAuthz()
    try {
        def tl = ec.entity.find("zenith.erp.saas.SaasTenant")
            .condition("organizationPartyId", orgId)
            .condition("statusId", "SaasTenantActive").list()
        if (tl) {
            result.isSaasTenant = true
            def pm = ec.entity.find("zenith.erp.saas.SaasPlanModule")
                .condition("planId", tl[0].planId).list()
            def mods = pm.collect { it.moduleId.toLowerCase() }
            result.hasAllAccess = mods.contains("all")
            // ZE-ROLES-001: role-scope the module list. This XHR is the /qapps menu source
            // (there the #zenith-saas-cfg div carrying the already-role-intersected
            // saasVisibleModulesJson is stripped, so the filter falls back to this). Without
            // this, a non-posOnly non-admin user with an extra role (e.g. Cashier + HR Manager)
            // saw EVERY plan module in the /qapps nav/tiles — an escalation APPEARANCE (the
            // server-side role gate still blocks the URLs). Intersect the plan modules with the
            // modules the user's ROLES actually grant (mirrors saasVisibleModulesJson). Admins /
            // ZENITH_ADMIN keep the full plan list; posOnly is trimmed by the client filter.
            // Fail-OPEN to the plan list on any error (never blank a real menu).
            if (!result.hasAllAccess && !result.isAdmin && !result.posOnly) {
                try {
                    def _myG = (ec.user.userGroupIdSet ?: []) as List
                    def _roleMods = new HashSet()
                    if (_myG) {
                        ec.entity.find("moqui.security.ArtifactAuthz")
                            .condition("userGroupId", "in", _myG)
                            .condition("authzTypeEnumId", "in", ["AUTHZT_ALLOW", "AUTHZT_ALWAYS"])
                            .list().each { if (it.artifactGroupId?.startsWith("Z_")) _roleMods.add(it.artifactGroupId.substring(2).toLowerCase()) }
                    }
                    mods = mods.findAll { _roleMods.contains(it) }
                } catch (Exception ex) { /* fail-open: keep the full plan list */ }
            }
            result.modules = mods
        }
    } catch (Exception e) {}
    finally { if (!d) ec.artifactExecution.enableAuthz() }
}
ec.web.sendJsonResponse(result)

def fid = ec.web.getRequest().getParameter("facilityId")
def org = ec.user.getPreference("ACTIVE_ORGANIZATION")
if (!fid) {
    ec.user.setPreference("ACTIVE_SHOP", "")   // All Shops (combined)
} else if (org && org != '_NA_') {
    boolean _d = ec.artifactExecution.disableAuthz()
    try {
        def f = ec.entity.find("mantle.facility.Facility").condition("facilityId", fid).one()
        if (f && f.facilityTypeEnumId == 'FcTpRetailStore' && f.ownerPartyId == org) {
            ec.user.setPreference("ACTIVE_SHOP", fid)
        }
        // else: cross-tenant / non-store id => ignore, preference unchanged
    } finally { if (!_d) ec.artifactExecution.enableAuthz() }
}
def ru = ec.web.getRequest().getParameter("returnUrl")
if (!ru || !ru.startsWith("/apps/zenith")) ru = "/apps/zenith"
context.zReturnUrl = ru

pre-actions.script:
modCanWrite = true
try {
    def _uri = ec.web?.getRequest()?.getRequestURI()
    def _segs = _uri ? _uri.split('/').findAll{it} : []
    int _zi = _segs.findIndexOf{ it.toLowerCase() == 'zenith' }
    def _rm = (_zi >= 0 && _zi + 1 < _segs.size()) ? _segs[_zi + 1].toLowerCase() : null
    def _gate = ['pos','sales','purchase','inventory','accounting','contacts','crm','hr','payroll',
        'attendance','timeoff','recruitment','expenses','manufacturing','quality','maintenance','fleet',
        'helpdesk','marketing','ecommerce','events','subscriptions','documents','approvals','integrations',
        'website','studio','plm','fieldservice','discuss','sign','project','timesheets','tax','pricing','barcode'] as Set
    if (_rm && _gate.contains(_rm)) {
        def _r = ec.service.sync().name("zenith.base.SecurityServices.check#ModuleWriteAccess").parameter("moduleId", _rm).call()
        modCanWrite = (_r?.canWrite != false)
    }
} catch (Throwable e) { modCanWrite = true }
invCanWrite = modCanWrite

